python3 -c "
import json

with open('/app/output/solution.json') as f:
    sol = json.load(f)

with open('/app/data/baseline_solution.json') as f:
    baseline = json.load(f)

with open('/app/data/policy.json') as f:
    policy = json.load(f)

# Job specs
jobs = [
    [{0: 6, 1: 5}, {1: 7, 2: 6}, {0: 5, 2: 8}],
    [{0: 5, 2: 7}, {1: 6, 2: 5}, {0: 7, 1: 8}],
    [{1: 4, 2: 6}, {0: 8, 1: 7}, {0: 6, 2: 5}],
    [{0: 7, 1: 6}, {1: 5, 2: 7}, {0: 4, 2: 6}]
]

downtime = {1: [(5, 20)], 2: [(12, 25)]}

def overlap(s, e, a, b):
    return s < b and a < e

sched_map = {(op['job'], op['op']): op for op in sol['schedule']}
base_map = {(op['job'], op['op']): op for op in baseline['schedule']}

errors = []

print('=== VALIDATION REPORT ===')
print()

# 1. Check precedence
print('1. Precedence constraints:')
for (j, o), op in sched_map.items():
    if o > 0:
        prev_op = sched_map.get((j, o - 1))
        if prev_op and op['start'] < prev_op['end']:
            errors.append(f'Precedence: Job {j} Op {o} starts at {op[\"start\"]} but Op {o-1} ends at {prev_op[\"end\"]}')
if not any('Precedence' in e for e in errors):
    print('  PASS: All precedence constraints satisfied')
else:
    for e in errors:
        if 'Precedence' in e:
            print(f'  FAIL: {e}')

# 2. Check machine validity and durations
print()
print('2. Machine and duration validity:')
for (j, o), op in sched_map.items():
    allowed = jobs[j][o]
    if op['machine'] not in allowed:
        errors.append(f'Machine: Job {j} Op {o} on invalid machine {op[\"machine\"]}')
    elif op['dur'] != allowed[op['machine']]:
        errors.append(f'Duration: Job {j} Op {o} has dur {op[\"dur\"]} but should be {allowed[op[\"machine\"]]}')
if not any('Machine' in e or 'Duration' in e for e in errors):
    print('  PASS: All machines valid and durations correct')
else:
    for e in errors:
        if 'Machine' in e or 'Duration' in e:
            print(f'  FAIL: {e}')

# 3. Check machine overlaps
print()
print('3. Machine overlap constraints:')
machine_ops = {}
for op in sol['schedule']:
    m = op['machine']
    if m not in machine_ops:
        machine_ops[m] = []
    for other in machine_ops[m]:
        if overlap(op['start'], op['end'], other['start'], other['end']):
            errors.append(f'Overlap: Job {op[\"job\"]} Op {op[\"op\"]} overlaps with Job {other[\"job\"]} Op {other[\"op\"]} on machine {m}')
    machine_ops[m].append(op)
if not any('Overlap' in e for e in errors):
    print('  PASS: No machine overlaps')
else:
    for e in errors:
        if 'Overlap' in e:
            print(f'  FAIL: {e}')

# 4. Check downtime
print()
print('4. Downtime constraints:')
for op in sol['schedule']:
    m = op['machine']
    for (a, b) in downtime.get(m, []):
        if overlap(op['start'], op['end'], a, b):
            errors.append(f'Downtime: Job {op[\"job\"]} Op {op[\"op\"]} [{op[\"start\"]},{op[\"end\"]}) overlaps [{a},{b}) on machine {m}')
if not any('Downtime' in e for e in errors):
    print('  PASS: No downtime violations')
else:
    for e in errors:
        if 'Downtime' in e:
            print(f'  FAIL: {e}')

# 5. Check no earlier than baseline
print()
print('5. No-earlier-than-baseline constraint:')
for (j, o), op in sched_map.items():
    base_op = base_map[(j, o)]
    if op['start'] < base_op['start']:
        errors.append(f'Earlier: Job {j} Op {o} starts at {op[\"start\"]} but baseline is {base_op[\"start\"]}')
if not any('Earlier' in e for e in errors):
    print('  PASS: No operations start earlier than baseline')
else:
    for e in errors:
        if 'Earlier' in e:
            print(f'  FAIL: {e}')

# 6. Check policy budgets
print()
print('6. Policy budget constraints:')
mc_count = sum(1 for k in sched_map if sched_map[k]['machine'] != base_map[k]['machine'])
shift_l1 = sum(abs(sched_map[k]['start'] - base_map[k]['start']) for k in sched_map)

max_mc = policy['change_budget']['max_machine_changes']
max_shift = policy['change_budget']['max_total_start_shift_L1']

print(f'  Machine changes: {mc_count} / {max_mc} - {\"PASS\" if mc_count <= max_mc else \"FAIL\"}'  )
print(f'  L1 start shift: {shift_l1} / {max_shift} - {\"PASS\" if shift_l1 <= max_shift else \"FAIL\"}')

if mc_count > max_mc:
    errors.append(f'Budget: Machine changes {mc_count} > {max_mc}')
if shift_l1 > max_shift:
    errors.append(f'Budget: L1 shift {shift_l1} > {max_shift}')

# 7. Summary
print()
print('=== SUMMARY ===')
print(f'Baseline makespan: {baseline[\"makespan\"]}')
print(f'New makespan: {sol[\"makespan\"]}')
print(f'Makespan ratio: {sol[\"makespan\"] / baseline[\"makespan\"]:.3f}')
print(f'Max ratio (guard): {policy[\"guards\"][\"max_makespan_ratio\"]}')
print()
if errors:
    print(f'VALIDATION FAILED with {len(errors)} error(s)')
    for e in errors:
        print(f'  - {e}')
else:
    print('VALIDATION PASSED - Schedule is feasible!')
"
